python3 -c "
import json
with open('/app/resources/treasury_bulletin_2010_06.json', 'r') as f:
    data = json.load(f)

# Print some keys
def print_structure(d, indent=0):
    if isinstance(d, dict):
        for k, v in d.items():
            print(' ' * indent + str(k))
            if isinstance(v, (dict, list)) and indent < 2:
                print_structure(v, indent + 2)
    elif isinstance(d, list) and len(d) < 10 and indent < 2:
        for item in d[:3]:
            print_structure(item, indent + 2)

print_structure(data)
" 2>&1 | head -40
